        // Company portal Dashboard: top performers, ranked by average evaluation score.
        public async Task<List<int>> GetCompanyTopPerformerTraineeIdsAsync(int companyId, int take)
        {
            var ranked = await _context.NFD_Enrollments
                .Where(e => e.CompanyId == companyId)
                .Select(e => new
                {
                    e.TraineeId,
                    AvgScore = e.Evaluations.Count() > 0 ? e.Evaluations.Average(ev => ev.Score) : 0
                })
                .OrderByDescending(x => x.AvgScore)
                .Take(take)
                .ToListAsync();

            return ranked.Select(x => x.TraineeId).ToList();
        }

        // Company portal Dashboard: at-risk trainees (low attendance or low scores).
        public async Task<List<int>> GetCompanyAtRiskTraineeIdsAsync(int companyId, int take)
        {
            const double attendanceThreshold = 80.0;
            const decimal scoreThreshold = 60m;

            var enrollments = await _context.NFD_Enrollments
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations)
                .Where(e => e.CompanyId == companyId)
                .ToListAsync();

            var atRisk = enrollments
                .Select(e =>
                {
                    var total = e.DailyAttendances.Count;
                    var present = e.DailyAttendances.Count(a => a.Status == NFD_AttendanceStatus.Present);
                    var attendanceRate = total > 0 ? (double)present / total * 100.0 : 100.0;
                    var avgScore = e.Evaluations.Count > 0 ? e.Evaluations.Average(ev => ev.Score) : 100m;

                    return new { e.TraineeId, attendanceRate, avgScore };
                })
                .Where(x => x.attendanceRate < attendanceThreshold || x.avgScore < scoreThreshold)
                .OrderBy(x => x.attendanceRate)
                .Take(take)
                .Select(x => x.TraineeId)
                .ToList();

            return atRisk;
        }

        // Trainer Reports: attendance rate / task completion rate / avg technical
        // grade across every batch this trainer is assigned to.
        public async Task<TrainerKpisDTO> GetTrainerKpisAsync(int trainerId)
        {
            var batchIds = await _context.NFD_BatchTrainers
                .Where(bt => bt.TrainerId == trainerId)
                .Select(bt => bt.BatchId)
                .ToListAsync();

            var enrollments = await _context.NFD_Enrollments
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations).ThenInclude(ev => ev.EvaluationTemplate)
                .Where(e => batchIds.Contains(e.BatchId))
                .ToListAsync();

            var totalDays = enrollments.SelectMany(e => e.DailyAttendances).Count();
            var presentDays = enrollments.SelectMany(e => e.DailyAttendances).Count(a => a.Status == NFD_AttendanceStatus.Present);
            var attendanceRate = totalDays > 0 ? (double)presentDays / totalDays * 100.0 : (double?)null;

            var tasksForBatches = await _context.NFD_Tasks
                .Where(t => batchIds.Contains(t.BatchId))
                .Select(t => t.TaskId)
                .ToListAsync();
            var submissions = await _context.NFD_Submissions
                .Where(s => tasksForBatches.Contains(s.TaskId))
                .ToListAsync();
            var totalRequiredTasks = tasksForBatches.Count * enrollments.Count;

            var completedTasks = submissions
                .Where(s => s.Status == NFD_SubmissionStatus.Graded)
                .Select(s => new { s.TaskId, s.TraineeId })
                .Distinct()
                .Count();

            double? taskCompletionRate = totalRequiredTasks > 0
                ? completedTasks * 100.0 / totalRequiredTasks
                : null;

            var technicalScores = enrollments
                .SelectMany(e => e.Evaluations)
                .Where(ev => ev.EvaluationTemplate != null && ev.EvaluationTemplate.Type == NFD_EvaluationType.Technical)
                .Select(ev => ev.Score)
                .ToList();
            var avgTechnicalGrade = technicalScores.Count > 0 ? (double)technicalScores.Average() : (double?)null;

            return new TrainerKpisDTO
            {
                AttendanceRate = Math.Round(attendanceRate ?? 0.0, 1),
                TaskCompletionRate = Math.Round(taskCompletionRate ?? 0.0, 1),
                AvgTechnicalGrade = Math.Round(avgTechnicalGrade ?? 0.0, 1)
            };
        }


        public async Task<TrainerKpisDTO> GetTrainerReportKpisAsync(
            int trainerId,
            int? batchId,
            int? traineeId)
        {
            // Only batches assigned to the current trainer.
            var allowedBatchIds = _context.NFD_BatchTrainers
                .AsNoTracking()
                .Where(bt => bt.TrainerId == trainerId)
                .Select(bt => bt.BatchId);

            if (batchId.HasValue)
            {
                if (!await allowedBatchIds.ContainsAsync(batchId.Value))
                {
                    throw new ArgumentException(
                        "The selected batch does not belong to this trainer.");
                }
            }

            var enrollmentsQuery = _context.NFD_Enrollments
                .AsNoTracking()
                .Where(e => allowedBatchIds.Contains(e.BatchId));

            if (batchId.HasValue)
                enrollmentsQuery = enrollmentsQuery
                    .Where(e => e.BatchId == batchId.Value);

            if (traineeId.HasValue)
                enrollmentsQuery = enrollmentsQuery
                    .Where(e => e.TraineeId == traineeId.Value);

            var enrollments = await enrollmentsQuery
                .Include(e => e.DailyAttendances)
                .Include(e => e.Evaluations)
                    .ThenInclude(ev => ev.EvaluationTemplate)
                .ToListAsync();

            // Attendance rate for selected records.
            var attendanceRecords = enrollments
                .SelectMany(e => e.DailyAttendances)
                .ToList();

            var attendanceRate = attendanceRecords.Count > 0
                ? Math.Round(
                    attendanceRecords.Count(a =>
                        a.Status == NFD_AttendanceStatus.Present)
                    * 100.0 / attendanceRecords.Count, 1)
                : 0.0;

            // Average technical grade for selected records.
            var technicalScores = enrollments
                .SelectMany(e => e.Evaluations)
                .Where(ev =>
                    ev.EvaluationTemplate != null &&
                    ev.EvaluationTemplate.Type == NFD_EvaluationType.Technical)
                .Select(ev => ev.Score)
                .ToList();

            var avgTechnicalGrade = technicalScores.Count > 0
                ? Math.Round((double)technicalScores.Average(), 1)
                : 0.0;

            // Tasks from selected batches.
            var selectedBatchIds = batchId.HasValue
                ? new List<int> { batchId.Value }
                : await allowedBatchIds.ToListAsync();

            var taskIds = await _context.NFD_Tasks
                .AsNoTracking()
                .Where(t => selectedBatchIds.Contains(t.BatchId))
                .Select(t => t.TaskId)
                .ToListAsync();

            var submissionsQuery = _context.NFD_Submissions
                .AsNoTracking()
                .Where(s => taskIds.Contains(s.TaskId));

            if (traineeId.HasValue)
            {
                // Only submissions belonging to this trainee's
                // enrollments in the selected scope.

                submissionsQuery = submissionsQuery
                    .Where(s => s.TraineeId == traineeId.Value);

            }

            var submissions = await submissionsQuery.ToListAsync();

            var taskCompletionRate = submissions.Count > 0
                ? Math.Round(
                    submissions.Count(s =>
                        s.Status == NFD_SubmissionStatus.Graded)
                    * 100.0 / submissions.Count, 1)
                : 0.0;

            return new TrainerKpisDTO
            {
                AttendanceRate = attendanceRate,
                TaskCompletionRate = taskCompletionRate,
                AvgTechnicalGrade = avgTechnicalGrade
            };
        }


        //==========================================================
        // Admin Reports: end-of-batch performance drill-down (paginated).


        // ==========================================================
        // Trainer Trainees Report
        // ==========================================================
        public async Task<List<TrainerTraineesReportRowDto>>
            GetTrainerTraineesReportRowsAsync(
                int trainerId,
                int? batchId,
                int? traineeId
            )
        {
            // Get batches assigned to this trainer
            var trainerBatchIds =
                await _context.NFD_BatchTrainers
                    .Where(bt =>
                        bt.TrainerId == trainerId
                    )
                    .Select(bt =>
                        bt.BatchId
                    )
                    .ToListAsync();


            // If a specific batch was requested,
            // make sure it belongs to this trainer.
            if (batchId.HasValue)
            {
                if (!trainerBatchIds.Contains(batchId.Value))
                {
                    return new List<TrainerTraineesReportRowDto>();
                }

                trainerBatchIds =
                    new List<int>
                    {
                batchId.Value
                    };
            }


            var enrollments =
                await _context.NFD_Enrollments

                    .Include(e =>
                        e.Trainee
                    )
                    .ThenInclude(t =>
                        t.User
                    )

                    .Include(e =>
                        e.Batch
                    )

                    .Include(e =>
                        e.DailyAttendances
                    )

                    .Include(e =>
                        e.Evaluations
                    )

                   .Where(e =>
    trainerBatchIds.Contains(e.BatchId) &&
    (!traineeId.HasValue || e.TraineeId == traineeId.Value)
)

                    .ToListAsync();


            var rows =
                enrollments
                    .Select(e =>
                    {
                        // ------------------------------------------
                        // Attendance
                        // ------------------------------------------

                        var totalDays =
                            e.DailyAttendances.Count;

                        var presentDays =
                            e.DailyAttendances.Count(
                                a =>
                                    a.Status ==
                                    NFD_AttendanceStatus.Present
                            );


                        var attendancePercentage =
                            totalDays > 0
                                ? Math.Round(
                                    (double)presentDays /
                                    totalDays *
                                    100.0,
                                    1
                                )
                                : 0.0;


                        // ------------------------------------------
                        // Evaluation Average
                        // ------------------------------------------

                        var averageScore =
                            e.Evaluations.Count > 0
                                ? Math.Round(
                                    e.Evaluations.Average(
                                        ev => ev.Score
                                    ),
                                    1
                                )
                                : 0m;


                        // ------------------------------------------
                        // Technical Level
                        // Same thresholds used in trainer frontend
                        // ------------------------------------------

                        var technicalLevel =
                            averageScore switch
                            {
                                >= 85 => "ممتاز",
                                >= 70 => "جيد",
                                >= 60 => "متوسط",
                                _ => "يحتاج تطوير"
                            };


                        return new TrainerTraineesReportRowDto
                        {
                            EnrollmentId =
                                e.EnrollmentId,

                            TraineeId =
                                e.TraineeId,

                            TraineeName =
                                e.Trainee?.User?.FullName,

                            BatchId =
                                e.BatchId,

                            BatchName =
                                e.Batch?.BatchName,

                            AttendancePercentage =
                                attendancePercentage,

                            AverageScore =
                                averageScore,

                            TechnicalLevel =
                                technicalLevel
                        };
                    })
                    .ToList();


            return rows;
        }
        // ==========================================================
        // Admin Reports - Companies Summary
        // ==========================================================
        public async Task<AdminCompaniesSummaryDTO> GetAdminCompaniesSummaryAsync()
        {
            var companies = await _context.NFD_Companies
                .AsNoTracking()
                .Select(c => new AdminCompanyReportItemDTO
                {
                    CompanyId = c.CompanyId,
                    CompanyName = c.CompanyName,
                    CommercialRegister = c.CommercialRegister,
                    WorkField = c.WorkField,
                    Address = c.Address,
                    Phone = c.Phone,
                    Email = c.Email,
                    Capacity = c.Capacity,
                    Status = c.Status.ToString(),

                    TraineesCount = _context.NFD_Enrollments
        .Where(e => e.CompanyId == c.CompanyId)
        .Select(e => e.TraineeId)
        .Distinct()
        .Count(),

                    ProgramsCount = _context.NFD_CompanyPrograms
        .Count(cp => cp.CompanyId == c.CompanyId),

                    BatchesCount = _context.NFD_Enrollments
        .Where(e => e.CompanyId == c.CompanyId)
        .Select(e => e.BatchId)
        .Distinct()
        .Count()
                })
                .ToListAsync();

            // Get company-specific enrollments with real batch and program data
            var enrollmentRows = await (
                from e in _context.NFD_Enrollments.AsNoTracking()
                join b in _context.NFD_Batches.AsNoTracking()
                    on e.BatchId equals b.BatchId
                join p in _context.NFD_Programs.AsNoTracking()
                    on b.ProgramId equals p.ProgramId
                join t in _context.NFD_Tracks.AsNoTracking()
                    on p.TrackId equals t.TrackId
                where e.CompanyId != null
                select new
                {
                    e.CompanyId,
                    e.TraineeId,
                    b.BatchId,
                    b.BatchName,
                    b.StartDate,
                    b.EndDate,
                    p.ProgramId,
                    ProgramName = p.Title,
                    TrackName = t.Name
                }
            ).ToListAsync();

            // Group by company, then program, then batch
            foreach (var company in companies)
            {
                var companyRows = enrollmentRows
                    .Where(x => x.CompanyId == company.CompanyId)
                    .ToList();

                company.Programs = companyRows
                    .GroupBy(x => new
                    {
                        x.ProgramId,
                        x.ProgramName,
                        x.TrackName
                    })
                    .Select(programGroup => new AdminCompanyProgramDTO
                    {
                        ProgramId = programGroup.Key.ProgramId,
                        ProgramName = programGroup.Key.ProgramName,
                        TrackName = programGroup.Key.TrackName,

                        BatchesCount = programGroup
                            .Select(x => x.BatchId)
                            .Distinct()
                            .Count(),

                        TraineesCount = programGroup
                            .Select(x => x.TraineeId)
                            .Distinct()
                            .Count(),

                        Batches = programGroup
                            .GroupBy(x => new
                            {
                                x.BatchId,
                                x.BatchName,
                                x.StartDate,
                                x.EndDate
                            })
                            .Select(batchGroup => new AdminCompanyBatchDTO
                            {
                                BatchId = batchGroup.Key.BatchId,
                                BatchName = batchGroup.Key.BatchName,
                                StartDate = batchGroup.Key.StartDate,
                                EndDate = batchGroup.Key.EndDate,

                                TraineesCount = batchGroup
                                    .Select(x => x.TraineeId)
                                    .Distinct()
                                    .Count()
                            })
                            .OrderBy(x => x.BatchId)
                            .ToList()
                    })
                    .OrderBy(x => x.ProgramId)
                    .ToList();
            }

            return new AdminCompaniesSummaryDTO
            {
                TotalCompanies = companies.Count,
                TotalHostedTrainees = companies.Sum(c => c.TraineesCount),
                Companies = companies
            };
        }

        // ==========================================================
        // Admin Reports - Master Trainees Transcript
        // Uses existing batch weighted calculation
        // ==========================================================
        public async Task<AdminTraineesTranscriptDTO>
            GetAdminTraineesTranscriptAsync(
                int pageNumber,
                int pageSize,
                int? companyId,
                int? batchId,
                int? traineeId
            )
        {
            pageNumber = Math.Max(1, pageNumber);
            pageSize = Math.Clamp(pageSize, 1, 1000);

            // Get only batches that have matching enrollments.
            var enrollmentQuery = _context.NFD_Enrollments
                .AsNoTracking()
                .AsQueryable();

            if (companyId.HasValue)
            {
                enrollmentQuery = enrollmentQuery.Where(
                    e => e.CompanyId == companyId.Value
                );
            }

            if (batchId.HasValue)
            {
                enrollmentQuery = enrollmentQuery.Where(
                    e => e.BatchId == batchId.Value
                );
            }

            if (traineeId.HasValue)
            {
                enrollmentQuery = enrollmentQuery.Where(
                    e => e.TraineeId == traineeId.Value
                );
            }

            var matchingEnrollmentIds = await enrollmentQuery
                .Select(e => e.EnrollmentId)
                .ToListAsync();

            var matchingBatchIds = await enrollmentQuery
                .Select(e => e.BatchId)
                .Distinct()
                .ToListAsync();

            var batches = await _context.NFD_Batches
                .AsNoTracking()
                .Include(b => b.Program)
                .Where(b => matchingBatchIds.Contains(b.BatchId))
                .OrderBy(b => b.BatchId)
                .ToListAsync();

            var matchingEnrollmentIdSet =
                matchingEnrollmentIds.ToHashSet();

            var rows = new List<AdminTraineeTranscriptRowDTO>();

            foreach (var batch in batches)
            {
                var stats = await CalculateBatchWeightedStatsAsync(
                    batch,
                    companyId
                );

                foreach (var stat in stats)
                {
                    var enrollment = stat.Enrollment;

                    if (!matchingEnrollmentIdSet.Contains(
                        enrollment.EnrollmentId))
                    {
                        continue;
                    }

                    rows.Add(new AdminTraineeTranscriptRowDTO
                    {
                        EnrollmentId = enrollment.EnrollmentId,

                        TraineeId = enrollment.TraineeId,

                        TraineeName =
                            enrollment.Trainee?.User?.FullName,

                        Major = enrollment.Trainee?.Major,

                        BatchId = batch.BatchId,
                        BatchName = batch.BatchName,

                        ProgramName = batch.Program?.Title,

                        CompanyId = enrollment.CompanyId,

                        CompanyName =
                            enrollment.Company?.CompanyName,

                        AttendanceRate =
                            Math.Round(stat.Attendance, 1),

                        TechnicalScore = stat.Technical,

                        BehavioralScore = stat.Behavioral,

                        FinalScore = stat.IsComplete
                            ? stat.Final
                            : null,

                        Level = stat.Level,

                        AttendanceWeight = batch.AttendanceWeight,
                        TasksWeight = batch.TasksWeight,
                        QuizzesWeight = batch.QuizzesWeight,
                        ProjectsWeight = batch.ProjectsWeight
                    });
                }
            }

            var orderedRows = rows
                .OrderBy(r => r.TraineeName)
                .ThenBy(r => r.BatchId)
                .ThenBy(r => r.EnrollmentId)
                .ToList();

            var totalCount = orderedRows.Count;

            var pagedRows = orderedRows
                .Skip((pageNumber - 1) * pageSize)
                .Take(pageSize)
                .ToList();

            return new AdminTraineesTranscriptDTO
            {
                Rows = pagedRows,
                TotalCount = totalCount,
                PageNumber = pageNumber,
                PageSize = pageSize
            };
        }
        // ==========================================================
        // Admin Portal ONLY - Dashboard Performance Period Filtering
        // ==========================================================
        public async Task<AdminDashboardSummaryDTO>
            GetAdminDashboardSummaryByPeriodAsync(
                DateTime? startDate,
                DateTime? endDate
            )
        {
            // Keep existing dashboard KPIs, charts, capacity and warnings.
            var summary = await GetAdminDashboardSummaryAsync();

            // Inclusive start date, exclusive end date.
            // Null dates mean no boundary (all periods).
            DateTime? from = startDate?.Date;
            DateTime? until = endDate?.Date.AddDays(1);

            if (from.HasValue && until.HasValue &&
                from.Value >= until.Value)
            {
                throw new ArgumentException(
                    "startDate cannot be later than endDate."
                );
            }

            bool InPeriod(DateTime date)
            {
                return (!from.HasValue || date >= from.Value) &&
                       (!until.HasValue || date < until.Value);
            }

            // All historical enrollments are eligible.
            // Only enrollments with actual period activity are classified.
            var enrollments = await _context.NFD_Enrollments
                .AsNoTracking()
                .Include(e => e.Trainee)
                    .ThenInclude(t => t.User)
                .Include(e => e.Company)
                .Include(e => e.Batch)
                .Include(e => e.DailyAttendances)
                    .ThenInclude(a => a.Excuses)
                .ToListAsync();

            var batchIds = enrollments
                .Select(e => e.BatchId)
                .Distinct()
                .ToList();

            var traineeIds = enrollments
                .Select(e => e.TraineeId)
                .Distinct()
                .ToList();

            var enrollmentIds = enrollments
                .Select(e => e.EnrollmentId)
                .ToList();

            var tasks = await _context.NFD_Tasks
                .AsNoTracking()
                .Where(t => batchIds.Contains(t.BatchId))
                .ToListAsync();

            var quizzes = await _context.NFD_Quizzes
                .AsNoTracking()
                .Where(q =>
                    batchIds.Contains(q.BatchId) &&
                    (q.Status == NFD_QuizStatus.Open ||
                     q.Status == NFD_QuizStatus.Closed ||
                     q.Status == NFD_QuizStatus.Archived))
                .ToListAsync();

            var projectBatches = await _context.NFD_ProjectBatches
                .AsNoTracking()
                .Where(p => batchIds.Contains(p.BatchId))
                .ToListAsync();

            var submissions = await _context.NFD_Submissions
                .AsNoTracking()
                .Where(s =>
                    traineeIds.Contains(s.TraineeId) &&
                    s.Status == NFD_SubmissionStatus.Graded)
                .ToListAsync();

            var quizAttempts = await _context.NFD_QuizAttempts
                .AsNoTracking()
                .Where(a =>
                    traineeIds.Contains(a.TraineeId) &&
                    a.SubmittedAt.HasValue)
                .ToListAsync();

            var projectGrades = await _context.NFD_TrainerProjectGrades
                .AsNoTracking()
                .Where(g => enrollmentIds.Contains(g.EnrollmentId))
                .ToListAsync();

            var traineeStats = enrollments.Select(enrollment =>
            {
                var batch = enrollment.Batch;

                // Attendance: exclude approved excuses.
                var attendanceRecords = enrollment.DailyAttendances
                    .Where(a =>
                        InPeriod(a.Date) &&
                        !a.Excuses.Any(x =>
                            x.Status == NFD_ExcuseStatus.Approved))
                    .ToList();

                bool hasAttendance = attendanceRecords.Count > 0;

                double attendance = hasAttendance
                    ? Math.Round(
                        attendanceRecords.Count(a =>
                            a.Status == NFD_AttendanceStatus.Present)
                        * 100.0 / attendanceRecords.Count,
                        2)
                    : 0;

                // Tasks: currently graded submissions, grouped by task.
                var batchTaskIds = tasks
                    .Where(t => t.BatchId == enrollment.BatchId)
                    .Select(t => t.TaskId)
                    .ToHashSet();

                var taskScores = submissions
                    .Where(s =>
                        s.TraineeId == enrollment.TraineeId &&
                        batchTaskIds.Contains(s.TaskId) &&
                        InPeriod(s.SubmittedAt))
                    .GroupBy(s => s.TaskId)
                    .Select(group =>
                    {
                        var latest = group
                            .OrderByDescending(s => s.SubmittedAt)
                            .First();

                        return ParseTaskGrade(latest.Grade);
                    })
                    .Where(score => score.HasValue)
                    .Select(score => (double)score!.Value)
                    .ToList();

                // Quizzes: best submitted attempt per quiz in the period.
                var batchQuizIds = quizzes
                    .Where(q => q.BatchId == enrollment.BatchId)
                    .Select(q => q.QuizId)
                    .ToHashSet();

                var quizScores = quizAttempts
                    .Where(a =>
                        a.TraineeId == enrollment.TraineeId &&
                        batchQuizIds.Contains(a.QuizId) &&
                        a.SubmittedAt.HasValue &&
                        InPeriod(a.SubmittedAt.Value))
                    .GroupBy(a => a.QuizId)
                    .Select(group =>
                        (double)group.Max(a => a.Percentage))
                    .ToList();

                // Projects: latest trainer grade per project in the period.
                var batchProjectIds = projectBatches
                    .Where(p => p.BatchId == enrollment.BatchId)
                    .Select(p => p.ProjectId)
                    .ToHashSet();

                var projectScores = projectGrades
                    .Where(g =>
                        g.EnrollmentId == enrollment.EnrollmentId &&
                        batchProjectIds.Contains(g.ProjectId) &&
                        InPeriod(g.GradedAt))
                    .GroupBy(g => g.ProjectId)
                    .Select(group =>
                        (double)group
                            .OrderByDescending(g => g.GradedAt)
                            .First()
                            .Score)
                    .ToList();

                // Use only components with real observations.
                // Missing components are not assigned zero.
                double weightedScore = 0;
                double applicableWeight = 0;

                if (batch.AttendanceWeight > 0 && hasAttendance)
                {
                    weightedScore += attendance *
                        (double)batch.AttendanceWeight;

                    applicableWeight +=
                        (double)batch.AttendanceWeight;
                }

                if (batch.TasksWeight > 0 && taskScores.Count > 0)
                {
                    weightedScore += taskScores.Average() *
                        (double)batch.TasksWeight;

                    applicableWeight +=
                        (double)batch.TasksWeight;
                }

                if (batch.QuizzesWeight > 0 && quizScores.Count > 0)
                {
                    weightedScore += quizScores.Average() *
                        (double)batch.QuizzesWeight;

                    applicableWeight +=
                        (double)batch.QuizzesWeight;
                }

                if (batch.ProjectsWeight > 0 && projectScores.Count > 0)
                {
                    weightedScore += projectScores.Average() *
                        (double)batch.ProjectsWeight;

                    applicableWeight +=
                        (double)batch.ProjectsWeight;
                }

                bool hasPerformance = applicableWeight > 0;

                double performance = hasPerformance
                    ? Math.Round(
                        weightedScore / applicableWeight, 2)
                    : 0;

                // At-risk classification takes precedence.
                // No attendance data does not mean zero attendance.
                bool isAtRisk =
                    (hasAttendance &&
                     attendance < (double)batch.AtRiskMinAttendance)
                    ||
                    (hasPerformance &&
                     performance < (double)batch.GoodMinScore);

                bool isExcellent =
                    !isAtRisk &&
                    hasAttendance &&
                    hasPerformance &&
                    performance >= (double)batch.ExcellentMinScore &&
                    attendance >= (double)batch.ExcellentMinAttendance;

                return new
                {
                    Enrollment = enrollment,
                    Attendance = attendance,
                    Performance = performance,
                    IsExcellent = isExcellent,
                    IsAtRisk = isAtRisk
                };
            }).ToList();

            AdminDashboardTraineeDTO ToDashboardTrainee(
                NFD_Enrollment enrollment,
                double attendance,
                double performance)
            {
                return new AdminDashboardTraineeDTO
                {
                    TraineeId = enrollment.TraineeId,
                    EnrollmentId = enrollment.EnrollmentId,
                    FullName = enrollment.Trainee.User?.FullName,
                    Major = enrollment.Trainee.Major,
                    CompanyName = enrollment.Company?.CompanyName,
                    GitHubUrl = enrollment.Trainee.GitHubUrl,
                    LinkedInUrl = enrollment.Trainee.LinkedInUrl,
                    AttendancePercent = attendance,
                    PerformancePercent = performance
                };
            }

            var topPerformers = traineeStats
                .Where(x => x.IsExcellent)
                .OrderByDescending(x => x.Performance)
                .ThenByDescending(x => x.Attendance)
                .GroupBy(x => x.Enrollment.TraineeId)
                .Select(group => group.First())
                .Select(x => ToDashboardTrainee(
                    x.Enrollment,
                    x.Attendance,
                    x.Performance))
                .ToList();

            var atRiskTrainees = traineeStats
                .Where(x => x.IsAtRisk)
                .OrderBy(x => x.Attendance)
                .ThenBy(x => x.Performance)
                .GroupBy(x => x.Enrollment.TraineeId)
                .Select(group => group.First())
                .Where(x => !topPerformers.Any(t =>
                    t.TraineeId == x.Enrollment.TraineeId))
                .Select(x => ToDashboardTrainee(
                    x.Enrollment,
                    x.Attendance,
                    x.Performance))
                .ToList();

            // Override only Admin dashboard performance metrics.
            summary.TopPerformers = topPerformers;
            summary.TopPerformersCount = topPerformers.Count;

            summary.TopPerformersAvgScore = topPerformers.Count > 0
                ? Math.Round(
                    topPerformers.Average(t => t.PerformancePercent),
                    1)
                : 0;

            summary.AtRiskTrainees = atRiskTrainees;
            summary.AtRiskCount = atRiskTrainees.Count;

            return summary;
        }


    }
}
